local ROOM_NUM_LEN = 9
local ViewBaseLayer = require("hall.NewViewBaseLayer")
local addNumber = class("addNumber", ViewBaseLayer)

function addNumber:ctor(callback, param)
    param = param or {}
    local csbPath = "hall/res/FriendScircle/addNumber.csb"
    addNumber.super.ctor(self, csbPath)
    self:enableMask(true)
    self.callback = callback
    self.param = param
    self.saveEnterNum = {}
    -- SCREEN_WIDTH = cc.Director:getInstance():getOpenGLView():getDesignResolutionSize().width
    -- SCREEN_HEIGHT = cc.Director:getInstance():getOpenGLView():getDesignResolutionSize().height
    -- self:setScale(SCREEN_WIDTH/1280,SCREEN_HEIGHT/720)
    self.tipStr:setString(param.tip or "")
	
	if param.curPoint then
		self.btnAddPartner_All:setVisible(true)
	else
		self.btnAddPartner_All:setVisible(false)
    end
    self:showRoomNum()
end

function addNumber:showRoomNum()
    local str = ""
    for i = 1, ROOM_NUM_LEN do
        if self.saveEnterNum[i] then
            str = str..self.saveEnterNum[i]
        end
    end
    self.txt_num:setString(str)
end

function addNumber:onClickBtnNum1(sender, event)
    if #self.saveEnterNum < ROOM_NUM_LEN then
        table.insert(self.saveEnterNum, "1")
        self:showRoomNum()
    end
end

