function addNumber:onClickBtnAddPartner()
    local strCode = table.concat(self.saveEnterNum)
    -- if not tonumber(strCode) then
    --     viewMgr:showTip({text = "请输入有效的数值！"})
    --     return
    -- end
    local data = clone(self.param)
    data.number = tonumber(strCode)
    data.strNumber = strCode

    local number = data.number or 0
    if self.param.minNum and number < self.param.minNum then
        viewMgr:showTip({text = self.param.minNum_error})
        return
    end
    if self.param.maxNum and number > self.param.maxNum then
        viewMgr:showTip({text = self.param.maxNum_error})
        return
    end
    self.callback(data)
    self:onClickBtnClose()
end

function addNumber:onClickBtnAddPartner_All()
    print(debug.traceback())
	if self.param.curPoint then
		local data = clone(self.param)
		data.number = self.param.curPoint
		self.callback(data)
	end
    self:onClickBtnClose()
end


function addNumber:onClickBtnDelete(sender, event)
    if #self.saveEnterNum > 0 then
        table.remove(self.saveEnterNum)
        self:showRoomNum()
    end
end

function addNumber:onClickBtnClose()
    self:removeSelf()
end

return addNumber